// Recebe DIRETO o output de um "Facebook Lead Ads Trigger" (um node por Página+
// Formulário — limitação da própria API do Meta/n8n) e monta o payload do contrato
// POST /api/leads/captura (LeadCaptureController), no mesmo formato do workflow
// "Insert Lead (Site)", só trocando source_channel/source_identifier e a extração
// de nome/e-mail/telefone/cidade/estado.
//
// Formato REAL confirmado do trigger (não é o formato cru da Graph API):
// { id, data: {pergunta: resposta, ...}, form: {id, name}, page: {id, name},
//   ad: {}, adset: {}, created_time }
// As perguntas em `data` variam por formulário/cliente (o texto da pergunta vira a
// chave) — por isso procura por PADRÃO (regex) em vez de nome fixo tipo
// 'full_name'/'phone_number', que só existem se a pergunta for do tipo "padrão" do
// Meta em inglês.
//
// Contrato importante: source_channel FIXO 'facebook_lead_ad' (bate com
// LeadChannel.kind, já seedado por organização) e source_identifier no formato
// EXATO "page_id:form_id" — é o que precisa estar cadastrado em
// client_lead_sources.external_id (aba "Fontes de Lead" da ficha do cliente) pra o
// lead ser identificado (201). Sem match, o endpoint responde 202 e o lead cai em
// triagem manual mesmo assim — nunca é descartado.

const item = $input.first().json;

// Normaliza a CHAVE da pergunta (minúsculo, sem acento/pontuação) pra comparar por
// padrão — cada cliente escreve a pergunta do jeito que quiser no formulário.
const normalize = (k) => k
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '_')
  .replace(/^_+|_+$/g, '');

const rawData = item.data || {};
const norm = {};
for (const [key, value] of Object.entries(rawData)) {
  norm[normalize(key)] = value;
}

// Tenta os padrões em ordem (mais específico primeiro) e devolve o valor do
// primeiro que bater com alguma chave.
const findByPatterns = (patterns) => {
  for (const p of patterns) {
    const key = Object.keys(norm).find((k) => p.test(k));
    if (key) return norm[key];
  }
  return null;
};

const email = findByPatterns([/^e_?mail$/, /e_?mail/]);
const phone = findByPatterns([/^telefone$/, /^celular$/, /^whatsapp$/, /^phone_number$/, /telefone|celular|whatsapp|fone|phone/]);
const name  = findByPatterns([/^nome_completo$/, /^nome$/, /^full_name$/, /^name$/, /nome|name/]);
const city  = findByPatterns([/^cidade$/, /^city$/, /cidade|city/]);

// state precisa caber em varchar(2) (sigla UF) no App — se a pergunta trouxer o
// nome do estado por extenso ("Santa Catarina"), manda null em vez de estourar a
// validação (max:2) e derrubar o lead inteiro por causa de um campo secundário.
const stateRaw = findByPatterns([/^uf$/, /^estado$/, /^state$/, /estado|_uf$|state/]);
const state = (stateRaw && stateRaw.length <= 2) ? stateRaw.toUpperCase() : null;

return {
  json: {
    source_channel:    'facebook_lead_ad',
    source_identifier: `${item.page?.id}:${item.form?.id}`,
    name:              name || null,
    email:             email || null,
    phone:             phone || null,
    form_name:         item.form?.name || item.form?.id || null,
    landing_page_url:  null,
    utm_source:        'facebook',
    utm_medium:        'lead_ad',
    utm_campaign:      item.adset?.name || null,
    utm_content:       item.ad?.name || null,
    utm_term:          null,
    city:              city || null,
    state:             state,
    event_id:          item.id || null,
    received_at:       item.created_time || new Date().toISOString(),
    raw_payload:       item,
  },
};
